<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">rabbitmqctl</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> list_user_permissions</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;app-user&quot;</span></span>
